            cursor: pointer;
          "
          >{{ $t('dashboard') }}</label
        >
      </q-btn>
    </div>
  </div> -->

  <div class="row no-wrap full-width">
    <div class="col">
      <div class="row full-width padding-left-35">
        <div class="col-6">
      <div class="full-width">
        <!--
          BOL-423: For e-invoice rejections (XML-only docs with no
          rendered PDF) the legacy iframe used to load
          /resource/document/{id}/{id}.pdf, which 404s and shows an
          ugly JSON blob ("No file for path …pdf found"). Switch to a
          dedicated XML viewer with line numbers + syntax highlight +
          error-line scroll-into-view so the user can see exactly
          which line in the supplier's XML triggered the rejection.
        -->
        <EInvoiceXmlViewer
          v-if="showXmlViewer"
          :doc-id="docId"
          :filename="record.filename"
          :error-line="einvoiceErrorLine"
        />
        <iframe
          v-else
          :src="path"
          title="Main menu"
          width="100%"
          class="scroll-height-100vh-125px error-iframe-light"
        ></iframe>
      </div>
    </div>

    <ErrorDetailsPanel
      :message="message"
      :exception="exception"
      :error-details="errorDetails"
      :validation-report="validationReport"
      :is-export-error="is_export_error"
      :restarting="restarting"
      :doc-id="docId"
      :doc-type="record.doc_type"
      :filename="record.filename"
      @go-to-field-validation="goToFieldValidation"
      @restart-document="restartDocument"
      @view-doc-flow="viewDocFlow"
      @create-ticket="openSupportSidebar"
    />
      </div>
    </div>

    <!--
      DOCB-13475: Support-ticket sidebar (same UX as the Validation
      Screen). Opens on demand with the doc id + full error report
      pre-filled into the ticket body.
    -->
    <div
      v-if="current_sidebar === 'support'"
      class="support-sidebar column no-wrap"
      data-test="error-support-sidebar"
    >
      <div class="row justify-end q-pa-xs">
        <q-btn
          flat
          round
          dense
          icon="close"
          :aria-label="$t('close')"
          @click="toggleSideBar('support')"
        />
      </div>
      <div class="col scrolle-y">
        <supportForm
          :doc-id="docId"
          :prefill-body="ticketBody"
          :prefill-subject="ticketSubject"
        />
      </div>
    </div>
  </div>
  <q-inner-loading :showing="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { CONSTANTS } from 'src/constants';
import { defineComponent, ref } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import type { dynamicObj } from 'src/pages/assets';
import { useDocumentStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import { useImageAuth } from 'src/composables/useImageAuth';
import { useSidebarPanel } from 'src/composables/useSidebarPanel';
import MessageBanner from 'src/components/MessageBanner.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import supportForm from 'src/components/field_validation/supportForm.vue';
import ErrorDetailsPanel from 'src/pages/Components/ErrorDetailsPanel.vue';
import EInvoiceXmlViewer from 'src/pages/Components/EInvoiceXmlViewer.vue';
import BackToSettings from 'src/pages/Settings/Components/BackToSettings.vue';
import { documentDetailApiService, documentListApiService } from 'src/services';
import {
  isEInvoiceRejection,
  parseEInvoiceMessage,
} from 'src/utils/einvoice/findingExplainer';

export default defineComponent({
  el: '#app',
    components: {
    MessageBanner,
    SubHeader,
    BackToSettings,
    ErrorDetailsPanel,
    EInvoiceXmlViewer,
    supportForm,
  },
  mounted() {
    this.init();
  },
  beforeRouteLeave: async function (to: any, from: any, next: any) {
    await this.resetAllStoreData();
    next();
  },
  unmounted: function () {
    // unmounted
  },
  data() {
    return {
      docId: '',
      filename: '',
      restarting: false,
    };
  },
  methods: {
    async init() {
      try {
        await this.getTokenQueryParam();
        this.processing = true;
        this.docId = this.$route.params.id as string;
        this.path =
          DOC2API_URL +
          '/resource/document/' +
          this.docId +
          '/' +
          this.docId +
          '.pdf?download=false' +
          '&' +
          this.tokenQueryParam;
        if (!this.path) {
          logInfo('pdf not found');
        }

        this.getErrorInfos();
        await this.getDocumentById(this.docId);
        this.checkExportError();
      } catch (err: any) {
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    async getErrorInfos() {
      const response = await documentDetailApiService.getDocumentError(
        this.docId,
      );

      if (response.message === null) {
        this.is_status_not_error = true;
        return;
      }

      // Handle both old format and new enhanced format
      if (response.error && response.failed_step) {
        // New enhanced API format
        this.message = response.error.message;
        this.exception = response.error.exception || '';
        this.errorDetails = response; // Store full enhanced response
      } else {
        // Legacy API format
        this.message = String(response.message);
        this.exception = response.exception || '';
        this.errorDetails = null;
      }

      this.exception = String(this.exception);

      // BOL-421-B: when the doc was rejected by the e-invoice validator,
      // the backend attaches the persisted ValidationReport to the
      // error response. Hand it through to ErrorDetailsPanel so the
      // BOL-418 ValidationReportPanel can render the L0–L4 findings.
      this.validationReport = response.validation_report || null;
    },

    checkExportError() {
      if (this.record.status === CONSTANTS.export_error) {
        this.is_export_error = true;
      }
    },

    async goToFieldValidation() {
      try {
        if (
          !this.record ||
          Object.keys(this.record).length === 0 ||
          this.record.success === false ||
          this.is_export_error === false
        ) {
          return;
        }

        this.processing = true;

        const response = await documentDetailApiService.setDocToReadyForValidation(this.docId);
        if (response.success === false) {
          throw response;
        }
        this.$router.push('/field_validation_v1/' + this.docId);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    async restartDocument() {
      this.restarting = true;
      try {
        let response;
        if (this.record.status === CONSTANTS.export_error) {
          response = await documentListApiService.restartExport( this.docId, false, true);
        } else {
          response = await documentDetailApiService.restartDocument(this.docId, );
        }
        if (response.success) {
          notify.success('Document restarted successfully');
          // Redirect to dashboard after restart
          setTimeout(() => {
            this.$router.push('/dashboard');
          }, 2000);
        } else {
          notify.error('Failed to restart document');
        }
      } catch (error) {
        notify.error('Error restarting document');
        logError('Restart error:', error);
      } finally {
        this.restarting = false;
      }
    },

    viewDocFlow() {
      this.$router.push('/doc_flow/' + this.docId);
    },

    /**
     * DOCB-13475: open the support-ticket sidebar, pre-filling the
     * ticket body with the full error report emitted by
     * ErrorDetailsPanel and a descriptive subject.
     */
    openSupportSidebar(report: string) {
      this.ticketBody = report || '';
      this.ticketSubject = `${this.$t('error')}: ${
        this.record?.filename || this.docId
      }`;
      this.current_sidebar = 'support';
    },
  },
  computed: {
    /**
     * BOL-423: An e-invoice was rejected by the validator pipeline-hook
     * either when the message has the rejection prefix OR when the
     * uploaded file is XML-only (no rendered PDF). In both cases the
     * iframe-PDF approach 404s — show the XML viewer instead.
     */
    showXmlViewer(): boolean {
      const filename = (this.record?.filename ?? '') as string;
      const isXmlFile = /\.(xml|cii\.xml)$/i.test(filename);
      const isPdfFile = /\.pdf$/i.test(filename);
      const isEdoc = Boolean(this.record?.is_edoc);
      const messageIsValidationReject = isEInvoiceRejection(
        `${this.message ?? ''} ${this.exception ?? ''}`,
      );
      // XML viewer requires a standalone XML file on storage. PDFs with
      // embedded e-invoice XML go through the iframe-PDF path instead —
      // the embedded XML isn't materialised as `{id}.xml` in S3 when the
      // pipeline rejects before the extraction step (e.g. ZUGFeRD/Factur-X
      // L0c profile-policy reject). Without this guard the XML viewer
      // requests `{id}.xml` and gets HTTP 404. Reported 2026-05-14
      // (facturx_basic_sample.pdf, DOCB-12133).
      if (isPdfFile) return false;
      return isXmlFile || isEdoc || messageIsValidationReject;
    },
    einvoiceErrorLine(): number {
      const parsed = parseEInvoiceMessage(
        `${this.message ?? ''} ${this.exception ?? ''}`,
      );
      return parsed?.lineNumber ?? 0;
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, bannerBg, doc_loaded, processing } = storeToRefs(doc_store);
    const { getDocumentById, saveDocument, resetAllStoreData } = doc_store;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();

    const { current_sidebar, toggleSideBar } = useSidebarPanel();

    return {
      record,
      bannerBg,
      doc_loaded,
      processing,
      saveDocument,
      getDocumentById,
      resetAllStoreData,

      current_sidebar,
      toggleSideBar,
      ticketBody: ref(''),
      ticketSubject: ref(''),

      path: ref(''),
      message: ref(''),
      exception: ref(''),
      is_status_not_error: ref(false),
      is_export_error: ref(false),
      errorDetails: ref(null as any),
      validationReport: ref(null as any),
      tokenQueryParam,
      getTokenQueryParam: refreshTokenParam,
    };
  },
});
</script>

<style lang="scss" scoped>
.i-frame-height {
